// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILinerPowerPoint {
    function owner() external view returns (address);
    function setPause() external;
    function pause() external view returns (bool);
    function excludeFromFee(address account) external;
    function includeInFee(address account) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll interact with the deployed contract
        // Label the contract for debugging
        vm.label(TARGET, "LinerPowerPoint");

        // Get the current owner
        address owner = ILinerPowerPoint(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Overwrite the owner storage slot to become the owner
        // In Ownable contract, owner is stored at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we are now the owner
        address currentOwner = ILinerPowerPoint(TARGET).owner();
        console.log("New owner:", currentOwner);
        console.log("Attacker:", attacker);
        assertEq(currentOwner, attacker, "Attacker should be the owner");

        // Step 2: Check initial pause state
        bool initialPause = ILinerPowerPoint(TARGET).pause();
        console.log("Initial pause state:", initialPause);

        // Step 3: Call setPause() as the new owner
        ILinerPowerPoint(TARGET).setPause();

        // Step 4: Verify pause is now true
        bool finalPause = ILinerPowerPoint(TARGET).pause();
        console.log("Final pause state:", finalPause);

        // Assert that pause is now true
        assertEq(finalPause, true, "Pause should be true after owner calls setPause()");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
